#include <iostream>
#include <vector>
#include <cassert>
#include <cmath>
#include <algorithm>
using namespace std;

using i64 = long long;
constexpr i64 MOD = 1000000007;

template<typename T>
class Matrix {
public:
    vector<vector<T>> elements;

    Matrix() = default;

    Matrix(size_t rows, size_t cols) : elements(rows, vector<T>(cols, 0)) {}

    Matrix(size_t n) : elements(n, vector<T>(n, 0)) {}

    size_t row_count() const { return elements.size(); }
    size_t col_count() const { return elements.empty() ? 0 : elements[0].size(); }

    const vector<T>& operator[](size_t idx) const { return elements[idx]; }
    vector<T>& operator[](size_t idx) { return elements[idx]; }

    static Matrix unit(size_t n) {
        Matrix res(n);
        for (size_t i = 0; i < n; ++i) res[i][i] = 1;
        return res;
    }

    Matrix& operator+=(const Matrix& other) {
        assert(row_count() == other.row_count() && col_count() == other.col_count());
        for (size_t i = 0; i < row_count(); ++i)
            for (size_t j = 0; j < col_count(); ++j)
                elements[i][j] = (elements[i][j] + other[i][j]) % MOD;
        return *this;
    }

    Matrix& operator-=(const Matrix& other) {
        assert(row_count() == other.row_count() && col_count() == other.col_count());
        for (size_t i = 0; i < row_count(); ++i)
            for (size_t j = 0; j < col_count(); ++j)
                elements[i][j] = (elements[i][j] - other[i][j] + MOD) % MOD;
        return *this;
    }

    Matrix& operator*=(const Matrix& other) {
        size_t r = row_count(), c = other.col_count(), m = col_count();
        assert(m == other.row_count());
        vector<vector<T>> temp(r, vector<T>(c, 0));
        for (size_t i = 0; i < r; ++i)
            for (size_t k = 0; k < m; ++k)
                for (size_t j = 0; j < c; ++j)
                    temp[i][j] = (temp[i][j] + elements[i][k] * other[k][j]) % MOD;
        elements = move(temp);
        return *this;
    }

    Matrix& operator^=(i64 exponent) {
        Matrix result = unit(row_count());
        Matrix base = *this;
        while (exponent > 0) {
            if (exponent & 1) result *= base;
            base *= base;
            exponent >>= 1;
        }
        elements = move(result.elements);
        return *this;
    }

    Matrix operator+(const Matrix& other) const { Matrix tmp(*this); tmp += other; return tmp; }
    Matrix operator-(const Matrix& other) const { Matrix tmp(*this); tmp -= other; return tmp; }
    Matrix operator*(const Matrix& other) const { Matrix tmp(*this); tmp *= other; return tmp; }
    Matrix operator^(i64 exponent) const { Matrix tmp(*this); tmp ^= exponent; return tmp; }

    friend ostream& operator<<(ostream& os, const Matrix& m) {
        for (size_t i = 0; i < m.row_count(); ++i) {
            os << "[";
            for (size_t j = 0; j < m.col_count(); ++j) {
                os << m[i][j] << (j + 1 == m.col_count() ? "]\n" : ",");
            }
        }
        return os;
    }

    T determinant_value() {
        Matrix<T> copy(*this);
        assert(row_count() == col_count());
        T det = 1;
        size_t n = row_count();
        for (size_t i = 0; i < n; ++i) {
            int pivot = -1;
            for (size_t j = i; j < n; ++j) {
                if (copy[j][i] != 0) {
                    pivot = j;
                    break;
                }
            }
            if (pivot == -1) return 0;
            if (i != pivot) {
                det = (det * (MOD - 1)) % MOD;
                swap(copy[i], copy[pivot]);
            }
            det = (det * copy[i][i]) % MOD;
            T inv = mod_inverse(copy[i][i], MOD);
            for (size_t j = 0; j < n; ++j) {
                copy[i][j] = (copy[i][j] * inv) % MOD;
            }
            for (size_t j = i + 1; j < n; ++j) {
                T factor = copy[j][i];
                for (size_t k = 0; k < n; ++k) {
                    copy[j][k] = (copy[j][k] - copy[i][k] * factor) % MOD;
                    if (copy[j][k] < 0) copy[j][k] += MOD;
                }
            }
        }
        return (det % MOD + MOD) % MOD;
    }

private:
    T mod_inverse(T a, T mod) {
        T m = mod, x = 0, y = 1;
        if (mod == 1) return 0;
        while (a > 1) {
            T q = a / mod;
            T t = mod;
            mod = a % mod;
            a = t;
            t = x;
            x = y - q * x;
            y = t;
        }
        if (y < 0) y += m;
        return y;
    }

public:
    void shift_rows() {
        Matrix<T> temp(row_count());
        for (size_t i = 0; i < K; ++i) {
            for (size_t j = 0; j < K; ++j) {
                temp[i][j] = elements[(i + K - 1) % K][(j + K - 1) % K];
            }
            temp[i][K] = elements[(i + K - 1) % K][K];
            temp[K][i] = elements[K][(i + K - 1) % K];
        }
        temp[K][K] = elements[K][K];
        elements = move(temp.elements);
    }
};

Matrix<i64> cache[70][35];

i64 pow_mod(i64 base, i64 exp) {
    if (exp == 0) return 1;
    i64 half = pow_mod(base, exp / 2);
    i64 result = (half * half) % MOD;
    if (exp & 1) result = (result * base) % MOD;
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    i64 N_val, K_val;
    cin >> N_val >> K_val;
    K = K_val;

    i64 depth = 0;
    i64 temp = N_val;
    while (temp >= K) {
        depth++;
        temp /= K;
    }

    cache[0][0] = Matrix<i64>::unit(K + 1);
    for (int i = 1; i < K + 1; ++i) cache[0][0][0][i] = 1;

    for (int i = 1; i < K; ++i) {
        cache[0][i] = cache[0][i-1];
        cache[0][i].shift_rows();
    }

    for (i64 level = 1; level <= depth; ++level) {
        cache[level][0] = cache[level-1][0];
        for (int i = 1; i < K; ++i) {
            cache[level][0] = cache[level-1][i] * cache[level][0];
        }
        for (int i = 1; i < K; ++i) {
            cache[level][i] = cache[level][i-1];
            cache[level][i].shift_rows();
        }
    }

    Matrix<i64> final(K + 1, 1);
    final[K][0] = 1;
    int shift_idx = 0;

    while (depth >= 0) {
        for (int i = 0; ; ++i) {
            if (pow_mod(K, depth) <= N_val) {
                N_val -= pow_mod(K, depth);
                final = cache[depth][shift_idx] * final;
                shift_idx = (shift_idx + 1) % K;
            } else {
                break;
            }
        }
        depth--;
    }

    i64 total = 0;
    for (int i = 0; i < K + 1; ++i) {
        total = (total + final[i][0]) % MOD;
    }
    cout << total << '\n';

    return 0;
}
